"""Render a sequence of ``Reference``s as a complete BibTeX file."""
from __future__ import annotations

from typing import Iterable

from pyfars.render.bibtex_entry import render as render_entry
from pyfars.substrate.types.reference import Reference

DEFAULT_HEADER = (
    "% This file is generated by `pyfars cite`. Do not edit by hand.\n"
    "% Source of truth: frontmatter `references:` blocks plus\n"
    "% optional `references/<key>.md` annotation files in the corpus.\n"
    "\n"
)


def render(refs: Iterable[Reference], *, header: str = DEFAULT_HEADER) -> str:
    sorted_refs = sorted(refs, key=lambda r: r.key.lower())
    return header + "\n".join(render_entry(r) for r in sorted_refs) + "\n"
